// gen_unicode_data.mjs — emits src/shared/unicode_data.ml: the per-codepoint
// NFKD decomposition and lowercase mapping tables used by the portable Fuzzy
// module so non-JS runtimes normalize search text the way
// String.prototype.normalize('NFKD')/toLowerCase() do.
//
// Usage: node scripts/gen_unicode_data.mjs > src/shared/unicode_data.ml
// (run whenever the toolchain's Unicode version changes)

const lit = (s) => {
  let out = '"';
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '"') out += '\\"';
    else if (ch === '\\') out += '\\\\';
    else if (cp >= 0x20 && cp < 0x7f) out += ch;
    else out += '\\u{' + cp.toString(16) + '}';
  }
  return out + '"';
};

const nfkd = [];
const lower = [];

for (let cp = 0; cp <= 0x10ffff; cp++) {
  if (cp >= 0xd800 && cp <= 0xdfff) continue; // surrogates have no scalar
  const ch = String.fromCodePoint(cp);
  const n = ch.normalize('NFKD');
  if (n !== ch) nfkd.push([cp, n]);
  const l = ch.toLowerCase();
  if (l !== ch) lower.push([cp, l]);
}

console.log('(* generated by scripts/gen_unicode_data.mjs — do not edit *)');
console.log('(* sorted (codepoint, replacement) tables; the entries are the');
console.log('   codepoints whose NFKD normalization / lowercase differs from');
console.log('   identity *)\n');
const emit = (name, rows) => {
  console.log(`let ${name} : (int * string) array = [|`);
  for (const [cp, s] of rows) {
    console.log(`  (${cp}, ${lit(s)});`);
  }
  console.log('|]\n');
};
emit('nfkd', nfkd);
emit('lower', lower);
console.log(`(* ${nfkd.length} nfkd + ${lower.length} lower entries, Unicode`);
console.log(`   tables of node ${process.version} *)`);
